test "applet manifest is complete" {
    try std.testing.expectEqual(@as(usize, 443), entries.len);
    var enabled: usize = 0;
    for (entries) |entry| {
        if (entry.default_enabled) enabled += 1;
    }
    try std.testing.expectEqual(@as(usize, 412), enabled);
}
